import{_ as a,o as t,c as i,ao as n}from"./chunks/framework.DqKglTHe.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"MagmaThermoKinematics.jl","text":"Thermal evolution of magmatic systems in 2D and 3D","tagline":"Dike and sill emplacement, magma-chamber overpressure and eruptions, convective cooling, tracers and zircon ages, on CPUs and GPUs.","actions":[{"theme":"brand","text":"Get Started","link":"/man/installation"},{"theme":"alt","text":"API Reference","link":"/man/listfunctions"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/boriskaus/MagmaThermoKinematics.jl"}],"image":{"src":"/logo.png","alt":"MagmaThermoKinematics.jl"}},"features":[{"icon":"🔥","title":"Thermal Modeling","details":"Simulate cooling, crystallization, latent heat effects, and evolving melt fractions, including convective cooling of melt-rich regions and out-of-plane heat loss in 2D sections.","link":"/man/numerics"},{"icon":"🧭","title":"Dike and Sill Emplacement","details":"Kinematic intrusion workflows in 2D and 3D, including randomized emplacement scenarios.","link":"/man/examples"},{"icon":"🌋","title":"Overpressure and Eruptions","details":"Chamber tracking on the grid, overpressure of a compressible water-bearing magma relaxing into the host rock, eruptions when a dike can reach the surface, host-rock displacement and a moving free surface.","link":"/man/eruptions"},{"icon":"💎","title":"Tracers and Zircon Ages","details":"Temperature–time paths of the emplaced magma and zircon age distributions (UCLA and Geneva methods, or zircon growth with ZirconGrowth.jl).","link":"/man/zircon_growth"},{"icon":"🗺️","title":"Data-Driven Setups","details":"Build the model (topography, geological units, initial temperature) with GeophysicalModelGenerator.jl and compare it with geophysical data.","link":"/man/example_mtk_gmg"},{"icon":"🔗","title":"Material Parameterizations","details":"GeoParams-based material properties and melting parameterizations for flexible physics setups.","link":"/man/MeltingParameterisations"},{"icon":"⚙️","title":"CPU and GPU Backends","details":"Built on KernelAbstractions, with the backend (threaded CPU or CUDA GPU) selected through `NumParam(backend=...)`. GPU backends are not tested in CI.","link":"/man/quickstart"},{"icon":"📚","title":"Full API Coverage","details":"Automatically generated API docs for public and internal symbols in the package.","link":"/man/listfunctions"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),r={name:"index.md"};function o(s,e,l,m,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="What-Is-MagmaThermoKinematics.jl?" tabindex="-1">What Is MagmaThermoKinematics.jl? <a class="header-anchor" href="#What-Is-MagmaThermoKinematics.jl?" aria-label="Permalink to &quot;What Is MagmaThermoKinematics.jl? {#What-Is-MagmaThermoKinematics.jl?}&quot;">​</a></h2><p>MagmaThermoKinematics.jl is a Julia package for simulating the thermal evolution of magmatic systems in 2D, 2D axisymmetric and 3D. It supports intrusive events such as dike and sill emplacement, tracks tracers, and couples thermal transport with material properties and phase/melting effects.</p><p>Beyond the thermal evolution, it can follow the magma chamber that forms from the intrusions:</p><ul><li><p><strong>Overpressure and eruptions</strong>: the overpressure of the chamber follows from the mass balance of a compressible, water-bearing magma and relaxes viscously into the host rock (with a shell viscosity from the temperature field and GeoParams creep laws). The chamber erupts once the overpressure is high enough for a dike to reach the surface; the erupted volume is removed, and the host rock and the free surface move accordingly (<a href="./man/eruptions">Eruptions</a>).</p></li><li><p><strong>Convective cooling</strong>: convection in melt-rich regions is parameterised by an effective conductivity from a Nusselt–Rayleigh relation, and heat lost out of the plane of a 2D section can be included (<a href="./man/numerics">Numerics and Physics</a>).</p></li><li><p><strong>Zircon ages</strong>: tracers record the temperature–time paths of the emplaced magma, from which zircon age distributions are computed (<a href="./man/zircon_growth">Zircon ages</a>).</p></li></ul><p>The package uses finite-difference discretizations, explicit or implicit (<a href="./man/implicit_solver">Implicit Enthalpy Solver</a>) time stepping on uniform or refined grids (<a href="./man/grid_refinement">Grid Refinement</a>), and runs on CPUs and GPUs.</p><h2 id="Start-Here" tabindex="-1">Start Here <a class="header-anchor" href="#Start-Here" aria-label="Permalink to &quot;Start Here {#Start-Here}&quot;">​</a></h2><ul><li><p>Installation and dependencies: <a href="./man/installation">Installation</a></p></li><li><p>First workflow with backend setup: <a href="./man/quickstart">Quick Start</a></p></li><li><p>End-to-end scripts and outputs: <a href="./man/examples">Examples</a></p></li><li><p>Complete symbol-level API: <a href="./man/listfunctions">Function Reference</a></p></li></ul>',7)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
